"""Pure failure-first controls for the fixed R18 definition-only CI bootstrap."""
import base64
import builtins
import json
import os
from pathlib import Path
import subprocess
import types
import unittest
from unittest.mock import Mock, patch

import r18_format_public_controls as controls

FIXTURE = {"wrapper":"","test":"","package":{"campaign_r18_document_inputs":"","campaign_r18_document_sources":"","campaign_r18_document_events":"","campaign_r18_document_admission":"","r18_verified_contract_driver":"","campaign_r18_document_format_process":"","campaign_r18_document_format":"","campaign_r06_sources":"","campaign_r06_browser_process":"","campaign_r18_format_public_files":"","campaign_r18_format_public_artifacts":""}}
WRAPPER = base64.b64decode(FIXTURE["wrapper"], validate=True)
TEST = base64.b64decode(FIXTURE["test"], validate=True)
PACKAGE = {name: base64.b64decode(value, validate=True) for name, value in FIXTURE["package"].items()}
ROOT = Path("/fixture")
NAMES = tuple(["test_only_exact_hosted_selection_without_cli_options","test_missing_selection_never_uses_a_suite_default","test_complete_bound_pair_is_only_a_proposal","test_safe_missing_history_prerequisite_remains_publishable_without_adoption","test_json_duplicate_nonfinite_invalid_utf8_or_depth_is_blocked","test_unknown_missing_extra_or_unbound_artifacts_are_blocked","test_actual_wrapper_status_and_every_settlement_flag_are_required","test_unknown_or_private_receipt_and_packet_fields_are_blocked","test_wrong_revision_candidate_packet_hash_or_after_state_is_blocked","test_source_path_duplicate_mode_and_tool_count_boundaries_are_blocked","test_summary_capture_never_exports_private_output_or_unknown_fields","test_exact_driver_arguments_include_required_fresh_output","test_fresh_private_name_is_not_created_and_collisions_are_preserved","test_extra_private_file_rejects_before_any_read","test_existing_public_directory_never_writes_or_deletes","test_source_capture_rejects_any_changed_size_blob_or_sha_before_import","test_summary_duplicate_nonfinite_or_wrong_phase_is_not_complete","test_invalid_admission_never_calls_publisher","test_publication_failure_preserves_every_artifact_without_cleanup"])
ENV = {"CAMPAIGN_PROOF": "R18", "CAMPAIGN_R18_SUITE": "source-format",
       "GITHUB_ACTIONS": "true", "RUNNER_OS": "Linux", "GITHUB_SHA": "a" * 40}


def fake_module(name, relative):
    module = types.ModuleType(name)
    module.__file__ = str(ROOT / relative)
    return module


def package():
    return {pin[0]: fake_module(pin[0], pin[1]) for pin in controls.PACKAGE_PINS}, dict(PACKAGE)


def prepared():
    reader = fake_module(controls.READER_ALIAS, controls.PACKAGE_PINS[0][1])
    reader.read_small, reader.tick = Mock(side_effect=[WRAPPER, TEST]), Mock()
    public = fake_module(controls.PUBLIC_ALIAS, controls.WRAPPER_PIN[1])
    public.CODE_PINS = controls.PACKAGE_PINS
    public.load_package = Mock(return_value=package())
    target = fake_module(controls.TEST_ALIAS, controls.TEST_PIN[1])
    return reader, public, target


def passing_class():
    methods = {name: lambda self: None for name in NAMES}
    methods["__module__"] = controls.TEST_ALIAS
    return type("PublicControls", (unittest.TestCase,), methods)


class BootstrapControls(unittest.TestCase):
    def test_selection_is_fixed_and_never_defaults_or_accepts_cli(self):
        self.assertEqual(controls.selection(ENV, ["fixed"]), "a" * 40)
        for key in ENV:
            for changed in ({k: v for k, v in ENV.items() if k != key}, ENV | {key: "wrong"}):
                with self.subTest(key=key), self.assertRaises(ValueError):
                    controls.selection(changed, ["fixed"])
        for argv in ([], ["fixed", "--output", "/elsewhere"]):
            with self.assertRaises(ValueError):
                controls.selection(ENV, argv)

    def test_uppercase_nonstring_and_wrong_length_revision_reject(self):
        for value in ("A" * 40, "a" * 39, "a" * 41, None, 12):
            with self.subTest(value=value), self.assertRaises(ValueError):
                controls.selection(ENV | {"GITHUB_SHA": value}, ["fixed"])

    def test_exact_wrapper_and_test_full_identities_are_required(self):
        for pin, raw in ((controls.WRAPPER_PIN, WRAPPER), (controls.TEST_PIN, TEST)):
            self.assertIs(controls.verified(raw, pin), raw)
            for index, changed in ((2, "0" * 40), (3, "0" * 64), (4, len(raw) + 1)):
                wrong = list(pin)
                wrong[index] = changed
                with self.assertRaises(ValueError):
                    controls.verified(raw, wrong)
            for bad in (raw + b"\n", bytearray(raw), raw[:-1]):
                with self.assertRaises(ValueError):
                    controls.verified(bad, pin)

    def test_capture_rejects_unlisted_path_or_alias_without_reader_call(self):
        reader = Mock()
        for index, value in ((0, "__main__"), (1, "other.py")):
            wrong = list(controls.WRAPPER_PIN)
            wrong[index] = value
            with self.assertRaises(ValueError):
                controls.capture(ROOT, tuple(wrong), reader, 20)
        reader.read_small.assert_not_called()

    def test_both_sources_are_captured_before_wrapper_or_test_definitions(self):
        reader, public, target = prepared()
        calls = []
        def make(name, relative, raw, root):
            calls.append((name, reader.read_small.call_count, raw, root))
            return {controls.READER_ALIAS: reader, controls.PUBLIC_ALIAS: public, controls.TEST_ALIAS: target}[name]
        with patch.object(controls, "module_from", side_effect=make):
            self.assertIs(controls.prepare(ROOT, 20), target)
        self.assertEqual([(name, count) for name, count, _raw, _root in calls],
                         [(controls.READER_ALIAS, 0), (controls.PUBLIC_ALIAS, 2), (controls.TEST_ALIAS, 2)])
        self.assertEqual(calls[0][2], PACKAGE[controls.PACKAGE_PINS[0][0]])
        self.assertNotEqual(controls.READER_ALIAS, controls.PACKAGE_PINS[0][0])
        self.assertEqual(calls[1][2], WRAPPER)
        self.assertEqual(calls[2][2], TEST)
        self.assertEqual(reader.read_small.call_args_list[0].args, (ROOT / controls.WRAPPER_PIN[1], 32768, 20))
        self.assertEqual(reader.read_small.call_args_list[1].args, (ROOT / controls.TEST_PIN[1], 32768, 20))
        public.load_package.assert_called_once_with(20)

    def test_symlink_nonregular_size_stability_deadline_and_close_reject_before_source_execution(self):
        for error in (OSError("symlink"), ValueError("regular-size-boundary"),
                      ValueError("input-growth"), ValueError("descriptor-input-changed"),
                      ValueError("named-input-changed"), ValueError("input-deadline"),
                      ValueError("descriptor-close-unconfirmed")):
            for first in (True, False):
                reader, _public, _target = prepared()
                reader.read_small.side_effect = error if first else [WRAPPER, error]
                with self.subTest(error=type(error).__name__, first=first), \
                        patch.object(controls, "module_from", return_value=reader) as create:
                    with self.assertRaises((ValueError, OSError)):
                        controls.prepare(ROOT, 20)
                    self.assertEqual(create.call_count, 1)

    def test_wrong_captured_wrapper_or_test_hash_never_executes_them(self):
        for values in ([WRAPPER + b"\n", TEST], [WRAPPER, TEST + b"\n"]):
            reader, _public, _target = prepared()
            reader.read_small.side_effect = values
            with patch.object(controls, "module_from", return_value=reader) as create:
                with self.assertRaises(ValueError):
                    controls.prepare(ROOT, 20)
                self.assertEqual(create.call_count, 1)

    def test_capture_checks_deadline_before_and_after_descriptor_read(self):
        reader = Mock()
        reader.read_small.return_value = WRAPPER
        reader.tick.side_effect = ValueError("input-deadline")
        with self.assertRaises(ValueError):
            controls.capture(ROOT, controls.WRAPPER_PIN, reader, 20)
        reader.read_small.assert_not_called()
        reader.tick.side_effect = [None, ValueError("input-deadline")]
        with self.assertRaises(ValueError):
            controls.capture(ROOT, controls.WRAPPER_PIN, reader, 20)
        reader.read_small.assert_called_once_with(ROOT / controls.WRAPPER_PIN[1], 32768, 20)

    def test_all_eleven_source_bytes_names_and_module_aliases_are_required(self):
        reader, public, target = prepared()
        modules, captured = package()
        controls.validate_package(ROOT, public, modules, captured)
        for pin in controls.PACKAGE_PINS:
            bad = dict(captured)
            bad[pin[0]] += b"\n"
            with self.subTest(name=pin[0]), self.assertRaises(ValueError):
                controls.validate_package(ROOT, public, modules, bad)
            bad_modules = dict(modules)
            bad_modules[pin[0]] = fake_module("__main__", pin[1])
            with self.assertRaises(ValueError):
                controls.validate_package(ROOT, public, bad_modules, captured)

    def test_extra_missing_package_source_or_wrong_fixed_pin_prevents_test_execution(self):
        for mutate in ("extra", "missing", "pin"):
            reader, public, target = prepared()
            modules, captured = package()
            if mutate == "extra":
                captured["unexpected"] = b"x"
            elif mutate == "missing":
                del modules[controls.PACKAGE_PINS[0][0]]
            else:
                public.CODE_PINS = public.CODE_PINS[:-1]
            public.load_package.return_value = modules, captured
            with patch.object(controls, "module_from", side_effect=[reader, public, target]) as create:
                with self.assertRaises(ValueError):
                    controls.prepare(ROOT, 20)
                self.assertEqual(create.call_count, 2)

    def test_only_nonmain_fixed_aliases_and_pinned_bytes_may_execute(self):
        for name, relative, raw in (("__main__", controls.WRAPPER_PIN[1], WRAPPER),
                                    ("arbitrary", controls.TEST_PIN[1], TEST),
                                    (controls.PUBLIC_ALIAS, "other.py", WRAPPER),
                                    (controls.PUBLIC_ALIAS, controls.WRAPPER_PIN[1], WRAPPER + b"\n")):
            with patch("builtins.compile") as compile_source:
                with self.assertRaises(ValueError):
                    controls.module_from(name, relative, raw, ROOT)
                compile_source.assert_not_called()

    def test_occupied_alias_is_not_overwritten(self):
        marker = types.ModuleType(controls.PUBLIC_ALIAS)
        with patch.dict(controls.sys.modules, {controls.PUBLIC_ALIAS: marker}), \
                patch("builtins.compile") as compile_source:
            with self.assertRaises(ValueError):
                controls.module_from(controls.PUBLIC_ALIAS, controls.WRAPPER_PIN[1], WRAPPER, ROOT)
            compile_source.assert_not_called()
            self.assertIs(controls.sys.modules[controls.PUBLIC_ALIAS], marker)

    def test_only_exact_publiccontrols_class_and_nineteen_names_are_selected(self):
        target = types.ModuleType(controls.TEST_ALIAS)
        target.PublicControls = passing_class()
        self.assertIs(controls.select_tests(target), target.PublicControls)
        for changed in ("extra", "missing", "class", "module"):
            bad = types.ModuleType(controls.TEST_ALIAS)
            bad.PublicControls = passing_class()
            if changed == "extra":
                bad.PublicControls.test_unapproved = lambda self: None
            elif changed == "missing":
                delattr(bad.PublicControls, NAMES[0])
            elif changed == "class":
                bad.PublicControls = object
            else:
                bad.__name__ = "__main__"
            with self.assertRaises(ValueError):
                controls.select_tests(bad)

    def test_real_default_io_process_and_wait_are_blocked_and_restored(self):
        before = builtins.open, os.open, subprocess.Popen
        with controls.mock_only():
            for call in (lambda: builtins.open("forbidden"), lambda: os.open("forbidden", 0),
                         lambda: subprocess.Popen(["forbidden"]), lambda: controls.time.sleep(1)):
                with self.assertRaises(RuntimeError):
                    call()
            with patch.object(os, "open", return_value=17):
                self.assertEqual(os.open("mock", 0), 17)
        self.assertEqual((builtins.open, os.open, subprocess.Popen), before)

    def test_full_nineteen_terminal_pass_records_are_required_for_green(self):
        with patch.object(controls.time, "monotonic", return_value=0):
            report = controls.run_controls(passing_class(), 20)
        self.assertEqual(report["classification"], "source-controls-green")
        self.assertEqual((report["count"], report["passed"], report["failed"], report["errors"], report["skipped"]),
                         (19, 19, 0, 0, 0))
        self.assertEqual([row["test"] for row in report["records"]], list(NAMES))
        self.assertEqual({row["status"] for row in report["records"]}, {"pass"})

    def test_failure_error_skip_expected_failure_and_unexpected_success_cannot_be_green(self):
        def fail(self):
            self.fail("private-body-must-never-be-exported")
        def error(self):
            raise RuntimeError("private-cookie-must-never-be-exported")
        def skip(self):
            self.skipTest("private-skip")
        for method in (fail, error, skip, unittest.expectedFailure(fail), unittest.expectedFailure(lambda self: None)):
            target = passing_class()
            setattr(target, NAMES[0], method)
            with patch.object(controls.time, "monotonic", return_value=0):
                report = controls.run_controls(target, 20)
            self.assertNotEqual(report["classification"], "source-controls-green")
            self.assertNotIn("private-", json.dumps(report))

    def test_subtest_failure_or_error_is_terminal_parent_failure(self):
        def failed(self):
            with self.subTest(secret="private-body"):
                self.assertEqual(1, 2)
        def errored(self):
            with self.subTest(secret="private-cookie"):
                raise RuntimeError("private-token")
        for method in (failed, errored):
            target = passing_class()
            setattr(target, NAMES[0], method)
            with patch.object(controls.time, "monotonic", return_value=0):
                report = controls.run_controls(target, 20)
            self.assertEqual(report["count"], 19)
            self.assertNotEqual(report["classification"], "source-controls-green")
            self.assertIn(report["records"][0]["status"], ("fail", "error"))
            self.assertNotIn("private-", json.dumps(report))

    def test_deadline_incomplete_duplicate_or_unknown_events_never_admit(self):
        target = passing_class()(NAMES[0])
        for mode in ("deadline", "incomplete", "duplicate", "unknown"):
            with patch.object(controls.time, "monotonic", return_value=21 if mode == "deadline" else 0):
                result = controls.SafeResult(20)
                if mode == "deadline":
                    with self.assertRaises(ValueError):
                        result.startTest(target)
                elif mode == "incomplete":
                    result.startTest(target)
                    result.stopTest(target)
                    self.assertNotEqual(result.report()["classification"], "source-controls-green")
                elif mode == "duplicate":
                    result.startTest(target)
                    with self.assertRaises(ValueError):
                        result.startTest(target)
                else:
                    target._testMethodName = "test_unapproved"
                    with self.assertRaises(ValueError):
                        result.startTest(target)

    def test_closed_report_never_exports_raw_exception_paths_or_output(self):
        with patch.object(controls.time, "monotonic", return_value=0):
            report = controls.run_controls(passing_class(), 20)
        self.assertEqual(set(report), {"schemaVersion", "id", "suite", "phase", "classification", "count",
                                     "passed", "failed", "errors", "skipped", "records", "formatterExecuted",
                                     "goExecuted", "autoAdoption", "semanticsVerified"})
        self.assertFalse(report["formatterExecuted"])
        self.assertFalse(report["goExecuted"])
        self.assertFalse(report["autoAdoption"])
        self.assertFalse(report["semanticsVerified"])
        for row in report["records"]:
            self.assertEqual(set(row), {"test", "status"})
